        pair = None
        for r, c in pts:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    q = (r + dr, c + dc)
                    if q in pts:
                        pair = ((r, c), q)
                        break
                if pair:
                    break
            if pair:
                break
        if not pair:
            continue

        (r1, c1), (r2, c2) = pair
        dr, dc = r2 - r1, c2 - c1

        # Continue the diagonal beyond the second pixel only.
        r, c = r2 + dr, c2 + dc
        while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
            out[r][c] = color
            r += dr
            c += dc

    return out
